entries.template:
{
  "PreToolUse": [
    {
      "matcher": "Edit|Write|MultiEdit|NotebookEdit",
      "hooks": [
        {
          "type": "command",
          "command": "python3 -c \"import sys, json, os; p = json.load(sys.stdin).get('tool_input', {}).get('file_path', ''); n = os.path.basename(p); blocked = n == '.env' or n.startswith('.env.') and not n.endswith(('.example', '.sample')); blocked and print('Editing ' + n + ' is blocked: it holds secrets. Ask the user to change it.', file=sys.stderr); sys.exit(2 if blocked else 0)\" # agentfleet:protect-secrets",
          "timeout": 5
        }
      ]
    }
  ]
}

{
  "PostToolUse": [
    {
      "matcher": "Edit|Write|MultiEdit",
      "hooks": [
        {
          "type": "command",
          "command": "python3 -c \"import sys, json, os, shutil, subprocess; p = json.load(sys.stdin).get('tool_input', {}).get('file_path', ''); root = os.environ.get('CLAUDE_PROJECT_DIR', '.'); local = lambda rel: os.path.join(root, rel) if os.path.isfile(os.path.join(root, rel)) else None; ext = os.path.splitext(p)[1].lower(); web = ('.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs', '.json', '.css', '.scss', '.md', '.vue', '.svelte', '.html', '.yml', '.yaml'); tool = local('node_modules/.bin/prettier') if ext in web else local('vendor/bin/pint') if ext == '.php' else shutil.which('ruff') if ext == '.py' else shutil.which('rustfmt') if ext == '.rs' else None; args = [tool, 'format', p] if tool and os.path.basename(tool) == 'ruff' else [tool, '--write', p] if tool and 'prettier' in tool else [tool, p]; os.path.isfile(p) and tool and subprocess.run(args, check=False)\" # agentfleet:format-after-edit",
          "timeout": 30
        }
      ]
    }
  ]
}
